  'person',
  '{"document_kind":"tour_product_full_page_v1","schema_version":7,"slug":"seoul-winter-seoraksan-nami-eobi-ice-valley-day-tour","locale":"fr","product_id":"seoul-winter-seoraksan-nami-eobi-ice-valley-day-tour","seo":{"pageTitle":"Excursion d''hiver depuis Séoul — Seoraksan, île de Nami et le mur de glace de la vallée d''Eobi | AtoC Korea","metaDescription":"Excursion d''une journée en autocar en saison hivernale au départ de Séoul : le parc national de Seoraksan sous la neige, les allées d''arbres givrées de l''île de Nami, et le mur de glace de la vallée d''Eobi à Gapyeong. Prise en charge à la station Hongik University ou à la station Myeongdong, entrée du parc et ferry de Nami inclus.","title":"Excursion d''hiver depuis Séoul — Seoraksan, île de Nami et le mur de glace de la vallée d''Eobi","description":"Une excursion d''une journée réservée à l''hiver au départ de Séoul, associant le parc national de Seoraksan sous la neige, l''île de Nami et le mur de glace de la vallée d''Eobi bâti par les villageois de Gapyeong.","primaryKeywords":["excursion hiver depuis Séoul","mur de glace vallée d''Eobi","Seoraksan en hiver depuis Séoul","île de Nami en hiver","excursion neige Corée du Sud une journée"],"ogImage":"https://www.atockorea.com/images/tours/seoraksan-national-park/seoraksan-ridge-view.webp"},"catalog_card":{"slug":"seoul-winter-seoraksan-nami-eobi-ice-valley-day-tour","title":"Spécial hiver depuis Séoul : Seoraksan, île de Nami et le mur de glace de la vallée d''Eobi","subtitle":"Une journée en autocar réservée à l''hiver — la neige sur le sommet le plus célèbre de Corée, Nami sous le givre, et un mur de glace bâti par un village","region":"Séoul → Gangwon-do → Gyeonggi-do (Gapyeong)","duration":"13.5 heures","stopsCount":3,"rating":0,"reviewCount":0,"badges":["Hiver uniquement","Saisonnier","Excursion depuis Séoul","Seoraksan","Mur de glace"],"tags":["Hiver uniquement","Saisonnier","Excursion depuis Séoul","Seoraksan","Île de Nami","Mur de glace"],"heroImage":"/images/tours/seoraksan-national-park/seoraksan-ridge-view.webp","thumbnail":"/images/tours/seoraksan-national-park/seoraksan-ridge-view.webp","priceLabel":"","shortCardDescription":"Ne fonctionne qu''au cœur de l''hiver : le Seoraksan sous la neige, les allées d''arbres givrées de l''île de Nami, et le mur de glace de 25 mètres que les villageois de Gapyeong font grandir chaque janvier sur une paroi rocheuse de la vallée."},"headlineLine1":"Excursion d''hiver depuis Séoul","headlineLine2":"Seoraksan, Nami et le mur de glace d''Eobi","price":{"amountLabel":"69","currency":"USD","per":"person","salePriceUsd":69},"hero":{"imageUrl":"/images/tours/seoraksan-national-park/seoraksan-ridge-view.webp","imagePosition":"center 40%","images":["/images/tours/seoraksan-national-park/seoraksan-ridge-view.webp"],"tagline":"Une journée en autocar en saison hivernale au départ de Séoul : le parc national le plus connu de Corée sous la neige, les allées givrées de l''île de Nami, et un mur de glace de 25 mètres qu''un village de Gapyeong construit à la main chaque janvier","pills":["Saison hivernale uniquement","Neige + mur de glace","Excursion en autocar"],"meta":{"duration":"13.5 heures","region":"Séoul → Gangwon-do → Gyeonggi-do (Gapyeong)","stops":"3 étapes","rating":0,"ratingStars":0}},"subnavItems":[{"id":"overview","label":"Aperçu"},{"id":"itinerary","label":"Itinéraire"},{"id":"details","label":"Détails"},{"id":"faq","label":"FAQ"},{"id":"reviews","label":"Avis"}],"glanceItems":[{"icon":"clock","label":"Durée","value":"13.5 heures"},{"icon":"camera","label":"Potentiel photo","value":"Très élevé","level":5},{"icon":"mountain","label":"Paysages","value":"Très élevés","level":5},{"icon":"footprints","label":"Marche","value":"Modérée","level":3},{"icon":"cloud-rain","label":"Sensibilité à la météo","value":"Élevée","level":2},{"icon":"users","label":"Adapté aux familles","value":"Modéré","level":3},{"icon":"gauge","label":"Rythme","value":"Soutenu","level":4}],"galleryItems":[{"id":1,"type":"photo","src":"/images/tours/seoraksan-national-park/seoraksan-ridge-view.webp","location":"Parc national de Seoraksan","caption":"Parc national de Seoraksan — photo 1","alt":"Parc national de Seoraksan — gallery image 1"},{"id":2,"type":"photo","src":"/images/tours/seoraksan-national-park/seoraksan-sinheungsa-ulsanbawi.webp","location":"Parc national de Seoraksan","caption":"Parc national de Seoraksan — photo 2","alt":"Parc national de Seoraksan — gallery image 2"},{"id":3,"type":"photo","src":"/images/tours/seoraksan-national-park/seoraksan-gwongumseong-cable-car.webp","location":"Parc national de Seoraksan","caption":"Parc national de Seoraksan — photo 3","alt":"Parc national de Seoraksan — gallery image 3"},{"id":4,"type":"photo","src":"/images/tours/seoraksan-national-park/seoraksan-sinheungsa-ulsan-rock.webp","location":"Parc national de Seoraksan","caption":"Parc national de Seoraksan — photo 4","alt":"Parc national de Seoraksan — gallery image 4"},{"id":5,"type":"photo","src":"/images/tours/nami-island/nami-metasequoia-sunset-lake.webp","location":"Île de Nami (Namiseom)","caption":"Île de Nami (Namiseom) — photo 1","alt":"Île de Nami (Namiseom) — gallery image 1"},{"id":6,"type":"photo","src":"/images/tours/nami-island/kakaotalk-20260510-222949305-04.webp","location":"Île de Nami (Namiseom)","caption":"Île de Nami (Namiseom) — photo 2","alt":"Île de Nami (Namiseom) — gallery image 2"},{"id":7,"type":"photo","src":"/images/tours/nami-island/kakaotalk-20260510-222949305-05.webp","location":"Île de Nami (Namiseom)","caption":"Île de Nami (Namiseom) — photo 3","alt":"Île de Nami (Namiseom) — gallery image 3"},{"id":8,"type":"photo","src":"/images/tours/nami-island/chatgpt-image-2026-5-11-01-12-05.webp","location":"Île de Nami (Namiseom)","caption":"Île de Nami (Namiseom) — photo 4","alt":"Île de Nami (Namiseom) — gallery image 4"}],"itineraryStops":[{"number":1,"time":"06:00 / 06:30","duration":"Créneau de 30 min","name":"Prise en charge (station Hongik University ou station Myeongdong)","category":"Prise en charge en autocar","description":"La prise en charge se fait à l''un des deux points de rendez-vous de Séoul : **(1) le Starbucks de la sortie 8 de la station Hongik University (Mapo-gu)** à 06:00 — la devanture du Starbucks se trouve immédiatement en haut de la sortie 8 ; OU **(2) la sortie 2 de la station Myeongdong (Jung-gu)** à 06:30 — le magasin phare NorthFace est le repère visible à côté de la sortie.\n\nLes deux points de prise en charge partagent le même autocar chauffé et les passagers de Hongik montent en premier. Merci d''être à votre point de rendez-vous **5 minutes avant l''heure prévue** — c''est un départ matinal par une matinée froide, et la journée ne fonctionne que si l''autocar atteint le Seoraksan à 09:30.\n\nHabillez-vous dès l''embarquement pour toute la journée, et pas pour le trajet jusqu''au métro : vous serez dehors par −5 °C ou moins à deux des trois étapes, et la dernière se déroule sur la glace. Le guide distribue une fiche d''itinéraire imprimée en coréen et en anglais et confirme le programme du jour, notamment si le téléphérique du Seoraksan fonctionne et ce que le village facture à Eobi.","image":null,"highlights":[],"timeUsed":["Arrivez à votre point de prise en charge 5 minutes avant l''heure prévue (~5 min)","Repérez l''autocar AtoC Korea devant la façade indiquée du Starbucks / NorthFace (~5 min)","Embarquement dans la file de prise en charge (~10 min)","Fiche d''itinéraire imprimée en coréen et en anglais distribuée à l''embarquement"],"whyOnRoute":"Les deux points de prise en charge couvrent les deux principaux pôles de visiteurs de Séoul — le quartier de l''université Hongik à Mapo-gu et Myeongdong à Jung-gu — et Hongik d''abord est l''ordre naturel pour un trajet vers le nord-est. Le départ à 06:00 n''est pas du remplissage : le Seoraksan est à environ trois heures de route et tout l''intérêt d''y aller en hiver est d''être sur le fond de vallée tant que la lumière est encore sur la neige. Un départ plus tardif placerait la visite du parc dans la platitude de l''après-midi et repousserait la dernière étape après la nuit tombée.","_poi_meta":null,"images":[],"imageCredits":[],"galleryItems":[]},{"name":"Parc national de Seoraksan","time":"≈ 09:30","number":2,"category":"Parc national (montagne)","duration":"120 min (2 heures)","timeUsed":["Arrivée à l''entrée de Seorakdong + orientation par le chauffeur-guide (~10 min)","Marche jusqu''au Tongildaebul + temple Sinheungsa (~15-20 min depuis le parking principal)","Téléphérique en option jusqu''à Gwongeumseong (~30-45 min, file d''attente comprise) OU promenade de Biseondae (~90 min)","Temps photo + regroupement au véhicule (~15 min)","Arrêt photo facultatif au pin vieux de 800 ans près du Sinheungsa (~5 min)"],"_poi_meta":{"poi_key":"seoraksan_national_park","verified":true,"match":"single_poi","kb_version":"1.27","verified_date":"2026-04-29","sources":["Korea Tourism Organization (VisitKorea — Seoraksan National Park (Outer Seorak) listing + IUCN Green List confirmation)","IUCN Green List of Protected and Conserved Areas (iucngreenlist.org — Seoraksan official entry + 2014 designation + 398.24 km² area)","Korea National Park Service (KNPS — Seoraksan National Park Office official site + endangered species management plan)","UNESCO World Heritage Centre (Mt. Sorak Biosphere Reserve 1982 designation + tentative World Heritage listing)","Wikipedia (Seoraksan National Park — corpus on 30 peaks, 2,000+ animal species, 1,400+ plant species)"]},"highlights":["5e parc national de Corée (1970) et première réserve de biosphère de l''UNESCO du pays (août 1982)","Tongildaebul : 14.6 m / 108 tonnes de bronze — le plus grand Bouddha de bronze assis de Corée (1997)","Temple Sinheungsa (652 apr. J.-C., Silla) — l''un des plus anciens temples bouddhistes encore actifs de Corée et un monastère de l''ordre Jogye","Téléphérique de Seorak en option, 1,132 m jusqu''à la plateforme de la forteresse de Gwongeumseong (700 m, légende de 1253)","30 sommets, plus de 2,000 espèces animales, 1,400-1,562 espèces végétales ; faune rare (porte-musc, goral, ours noir d''Asie)","Entrée du parc GRATUITE depuis mai 2023 (elle coûtait 3,500 KRW) ; le téléphérique reste payant","**Catégorie II de l''UICN (parc national) depuis 2005 + Liste verte des aires protégées de l''UICN depuis 2014** — premier parc national de Corée à entrer sur la Liste verte lors de la phase pilote, aux côtés de l''Odaesan et du Jirisan","**Première réserve de biosphère de l''UNESCO en Corée depuis août 1982** + **inscrit sur la liste indicative du patrimoine mondial de l''UNESCO** — une reconnaissance combinée qu''aucun autre parc national coréen n''égale","**Pièce maîtresse de la conservation du goral à longue queue** : population stable d''environ 260 individus (vulnérable sur la Liste rouge de l''UICN) — le parc gère 10 zones de protection spéciale couvrant 39 km² (10% de la superficie totale du parc) pour les espèces menacées"],"smartNotes":{"photo":"Le Bouddha de bronze Tongildaebul se détachant sur le granit saupoudré de neige, c''est le cliché. En hiver, la ligne de crête d''Ulsanbawi est généralement visible depuis l''esplanade d''entrée les matins clairs.","facilities":"Centre d''accueil, cafés, restaurants et boutiques de souvenirs à l''entrée de Sogongwon. L''espace intérieur pour se réchauffer est limité les jours d''affluence hivernale.","tip":"Ne construisez pas votre visite autour du téléphérique. Ses horaires d''hiver changent chaque jour et il ferme pour vent et verglas plus souvent qu''aux autres saisons ; les files peuvent aussi être longues par temps clair. Considérez-le comme un bonus, pas comme un acquis. Habillez-vous pour −5 °C à +5 °C au pied de la montagne, avec un fort refroidissement éolien."},"whyOnRoute":"Le Seoraksan ouvre la journée parce qu''il est à la fois l''étape la plus éloignée et la plus dépendante de la lumière. À 09:30, la neige sur les crêtes de granit est encore propre et la vallée ne s''est pas encore couverte, ce qui est toute la raison de rouler trois heures pour venir. Deux heures à l''entrée de Sogongwon suffisent pour le grand Bouddha de bronze Tongildaebul, le temple Sinheungsa et les sentiers de la basse vallée à un rythme hivernal — pas assez pour une tentative de sommet, et c''est délibéré. Commencer par là permet aussi d''expédier le plus long trajet de la journée avant que quiconque ne soit fatigué ou n''ait froid.","convenience":{"restroom":"Dans la zone de l''entrée principale, à la gare du téléphérique, dans l''enceinte du temple Sinheungsa et le long des principaux sentiers","parking":"Disponible à l''entrée principale de Sogongwon (payant)"},"description":"Le Seoraksan a été le 5e parc national de Corée — classé en mars 1970 — et reste la première réserve de biosphère de l''UNESCO du pays, reconnue en août 1982 pour son exceptionnelle biodiversité de montagne. \n\nLe parc s''étend sur environ 398 km² à cheval sur quatre villes et comtés, avec 30 sommets nommés dominés par le Daecheongbong (1,708 m, 3e plus haut sommet de Corée) et la célèbre formation granitique à six piliers du rocher d''Ulsanbawi. L''entrée du parc est GRATUITE depuis la suppression, en mai 2023, des frais de 3,500 KRW qui étaient historiquement perçus pour le compte du temple Sinheungsa — ce sont désormais des fonds publics qui entretiennent le temple. \n\nDepuis l''entrée principale de Sogongwon (Seorak extérieur / Oeseorak), la visite type de 3 heures couvre trois temps forts : le **Tongildaebul (grand Bouddha de l''Unification)** — 14.6 m et 108 tonnes de bronze, le plus grand Bouddha de bronze assis de Corée, érigé en 1997 en prière pour la réunification coréenne, avec un petit sanctuaire dédié à la bodhisattva Guan Yin aménagé dans sa base ; le **temple Sinheungsa** lui-même, fondé en 652 par Jajangyulsa sous le royaume de Silla et considéré comme l''un des plus anciens temples bouddhistes encore actifs de Corée, ainsi qu''un temple de l''ordre Jogye ; et, en option, le **téléphérique de Seorak** (1,132 m de distance parcourue, ~10 min l''aller jusqu''à la plateforme de la forteresse de Gwongeumseong, à 700 m — aller-retour adulte 16,000 KRW / enfant 12,000 KRW, billetterie sur place uniquement, sans réservation préalable, avec des files souvent longues de plusieurs heures au pic des feuillages d''octobre). \n\nLa forteresse de Gwongeumseong, au sommet, porte une légende vivace : elle aurait été érigée en une seule journée lors de l''invasion mongole de 1253, sous la dynastie Goryeo, par deux généraux nommés Kwon et Kim — d''où Gwon-geum-seong. Les marcheurs actifs qui renoncent au téléphérique peuvent choisir à la place la promenade facile de 1.5 km au bord du torrent jusqu''au rocher de Biseondae (pavée sur la plus grande partie), la boucle du « rocher branlant » de Heundeulbawi (1.5 h dans chaque sens, avec des marches de pierre), ou la montée de 600 m jusqu''à la grotte de Geumganggul (~1 h 40 aller-retour).","visitBasics":{"hours":"Parc ouvert toute l''année ; temple Sinheungsa à partir de 06:00. Le téléphérique de Gwongeumseong fonctionne en hiver, mais ses horaires changent chaque jour avec la météo et il est suspendu par vent fort ou par verglas — l''exploitant publie l''horaire chaque matin, ce n''est donc jamais garanti","closed":"Ouvert toute l''année, mais les sentiers d''altitude ferment de façon saisonnière pour la prévention des incendies et la sécurité — généralement de la mi-novembre à la mi-décembre, puis de nouveau à partir de la mi-février environ. Cet itinéraire n''emprunte que les sentiers de basse vallée près de l''entrée, qui ne sont pas concernés","admission":"Entrée du parc GRATUITE (les frais de ₩3,500 ont été supprimés en mai 2023). Téléphérique aller-retour ₩16,000 adulte, billetterie sur place uniquement, NON inclus dans ce circuit et sans garantie de fonctionnement","walking":"Facile à modérée sur le fond de vallée — chemins pavés et marches jusqu''au Sinheungsa et au Tongildaebul, enneigés et glissants par endroits. Aucune randonnée n''est prévue ; des chaussures solides et antidérapantes sont indispensables"},"image":"/images/tours/seoraksan-national-park/seoraksan-ridge-view.webp","images":["/images/tours/seoraksan-national-park/seoraksan-ridge-view.webp","/images/tours/seoraksan-national-park/seoraksan-sinheungsa-ulsanbawi.webp","/images/tours/seoraksan-national-park/seoraksan-gwongumseong-cable-car.webp","/images/tours/seoraksan-national-park/seoraksan-sinheungsa-ulsan-rock.webp"],"imageCredits":[{"url":"/images/tours/seoraksan-national-park/seoraksan-ridge-view.webp","source":"atoc-korea"},{"url":"/images/tours/seoraksan-national-park/seoraksan-sinheungsa-ulsanbawi.webp","source":"atoc-korea"},{"url":"/images/tours/seoraksan-national-park/seoraksan-gwongumseong-cable-car.webp","source":"atoc-korea"},{"url":"/images/tours/seoraksan-national-park/seoraksan-sinheungsa-ulsan-rock.webp","source":"atoc-korea"}],"galleryItems":[{"id":1,"type":"photo","src":"/images/tours/seoraksan-national-park/seoraksan-ridge-view.webp","location":"Parc national de Seoraksan","caption":"Parc national de Seoraksan — photo 1","alt":"Parc national de Seoraksan — gallery image 1"},{"id":2,"type":"photo","src":"/images/tours/seoraksan-national-park/seoraksan-sinheungsa-ulsanbawi.webp","location":"Parc national de Seoraksan","caption":"Parc national de Seoraksan — photo 2","alt":"Parc national de Seoraksan — gallery image 2"},{"id":3,"type":"photo","src":"/images/tours/seoraksan-national-park/seoraksan-gwongumseong-cable-car.webp","location":"Parc national de Seoraksan","caption":"Parc national de Seoraksan — photo 3","alt":"Parc national de Seoraksan — gallery image 3"},{"id":4,"type":"photo","src":"/images/tours/seoraksan-national-park/seoraksan-sinheungsa-ulsan-rock.webp","location":"Parc national de Seoraksan","caption":"Parc national de Seoraksan — photo 4","alt":"Parc national de Seoraksan — gallery image 4"}]},{"number":3,"time":"≈ 11:45","duration":"50 min","name":"Déjeuner près de Sokcho (à vos frais)","category":"Pause déjeuner","description":"L''autocar s''arrête une cinquantaine de minutes dans un restaurant local près du Seoraksan ou du côté de Sokcho, après le parc. Le déjeuner n''est **pas inclus** — vous commandez et payez ce que vous voulez, généralement ₩10,000-15,000 par personne.\n\nNous sommes ici dans la ceinture des fruits de mer de la côte est : les choix locaux sont donc le **hoedeopbap** (poisson cru sur du riz), le poisson grillé, ou le **sundubu jjigae** — le ragoût de tofu soyeux pour lequel le quartier de Cheoksan à Sokcho est connu, et qui est exactement ce qu''il faut manger après deux heures dans la neige. Les options végétariennes sont limitées ; prévenez le guide le matin et il appellera à l''avance.\n\nPrévoyez des espèces ou une carte. Ces cinquante minutes sont volontairement enlevées — le trajet de retour vers l''ouest jusqu''à Nami dure deux heures et les deux dernières étapes ont toutes deux besoin de la lumière du jour.","image":null,"highlights":[],"timeUsed":["L''autocar se gare et le guide accompagne le groupe jusqu''au restaurant (~5 min)","Commander et manger (~35 min)","Payer individuellement et se regrouper à l''autocar (~10 min)"],"whyOnRoute":"Le déjeuner vient juste après le Seoraksan parce que c''est le seul moment de la journée où un vrai arrêt assis ne coûte pas de lumière du jour. Tout ce qui suit dépend du temps : Nami a besoin de lumière pour ses allées d''arbres, et Eobi doit être atteint avant la fermeture de la zone d''observation du village. Manger ici permet aussi de se réchauffer juste après la marche la plus froide de la journée.","_poi_meta":null,"images":[],"imageCredits":[],"galleryItems":[]},{"name":"Île de Nami (Namiseom)","time":"≈ 14:35","number":4,"category":"Île accessible en ferry et haut lieu du K-drama","duration":"120 min (2 heures)","timeUsed":["Traversée en ferry depuis le quai de Gapyeong (5-10 minutes, file d''attente comprise)","Temps de marche libre le long des allées de métaséquoias / ginkgos / pins de Corée — circuit d''une demi-île, ~3 km","Location de vélo en option (simple 7,000 / tandem 14,000 KRW de l''heure) ou petit train électrique bleu (3,000 KRW l''aller vers l''UNICEF Hall)","Courte pause gourmande sur l''île (Sonata Cafe, hotteok, latte à la patate douce)","Ferry de retour vers la terre ferme"],"_poi_meta":{"poi_key":"nami_island","verified":true,"match":"single_poi","kb_version":"1.27","verified_date":"2026-04-29","sources":["Korea Tourism Organization (VisitKorea — Nami Island official listing + visa fee schedule)","Naminara Republic Official Site (namisum-en.imweb.me — own corpus on cultural-independence brand)","UNICEF Korea (Nami Island 2010 Child Friendly Park designation + International Children''s Book Festival)","KBS / Korea Times (Winter Sonata 2002 production retrospectives + Japanese tourism boom coverage)","Wikipedia (Namiseom — open corpus on General Nami history + Cheongpyeong Dam 1944 origin)"]},"highlights":["Île fluviale en demi-lune, ~460,000 m² / 5 km de circonférence ; nommée d''après le général Nami (1441-1468)","Allée iconique bordée de métaséquoias — lieu de tournage emblématique de Winter Sonata (2002)","« Naminara Republic » autoproclamée depuis 2006 — drapeau, monnaie et passeport propres (concept touristique)","Ferry de 5 min depuis le quai de Gapyeong (08:00-21:00, toutes les 10-20 min en période de pointe)","Faune sur l''île : paons (dont de rares albinos), autruches, lapins sauvages, écureuils","**Terre formée en 1944** lorsque le barrage de Cheongpyeong, construit par les Japonais, a relevé la rivière Bukhan","**Désignation UNICEF Child Friendly Park en 2010** + Nami Island Arts & Education accueille **plus de 600 spectacles/expositions/festivals par an**"],"smartNotes":{"photo":"L''allée de métaséquoias est le cliché mondialement connu de Winter Sonata — au mieux en automne (doré, de fin octobre à début novembre) ou en hiver (neige). L''allée des ginkgos des amoureux au bord de la rivière, côté sud, est plus calme et tout aussi photogénique. Un paon albinos apparaît de temps à autre près de l''allée des amoureux.","facilities":"Les restaurants de l''île servent une cuisine coréenne réconfortante (hotteok, latte à la patate douce, tteok-galbi). Le Sonata Cafe, installé dans un hanok traditionnel, est l''adresse emblématique. Guichet acceptant les cartes étrangères au quai de Gapyeong — les distributeurs de billets n''acceptent pas les cartes étrangères, adressez-vous au guichet.","tip":"Meilleures saisons : printemps (cerisiers en fleurs, avril-mai), automne (ginkgos dorés et érables rouges en octobre), hiver (de décembre à février, chemins silencieux sous la neige qui rappellent Winter Sonata). Évitez la file du ferry le dimanche en fin d''après-midi."},"whyOnRoute":"Nami se place au milieu de la journée parce que c''est la seule étape qui a besoin à la fois de la lumière du jour et d''un bateau. Les allées de métaséquoias et de ginkgos sous le givre sont ce qui vaut la traversée en hiver, et elles ont besoin de lumière ; le pont du ferry est par ailleurs exposé, une traversée en milieu d''après-midi est donc plus confortable qu''une traversée tardive. La placer après le Seoraksan découpe aussi le long trajet vers l''ouest en deux étapes gérables plutôt qu''en une seule.","convenience":{"restroom":"Plusieurs sur l''île et au quai de Gapyeong","parking":"Quai de Gapyeong 6,000 KRW voiture particulière / 10,000 KRW grand véhicule"},"description":"L''île de Nami ouvre le deuxième chapitre de la journée par une traversée en ferry de 5 minutes depuis le quai de Gapyeong vers une île fluviale en forme de demi-lune, sur la rivière Bukhan. D''environ **460,000 m² (140,000 pyeong) et ~5 km de circonférence**, Namiseom porte le nom du **général Nami (Nam Yi, 1441-1468)**, un commandant militaire de l''époque Joseon exécuté à 28 ans après avoir été faussement accusé de trahison sous le règne du roi Yejong. \n\nÀ l''origine, l''île n''émergeait qu''en période de crue ; **en 1944, le gouvernement colonial japonais a construit le barrage de Cheongpyeong, relevant le niveau de la rivière et faisant de Nami une île permanente**. Elle a connu une renommée mondiale **en 2002 comme lieu de tournage du drama de la KBS « Winter Sonata »**, avec Bae Yong-joon et Choi Ji-woo — le déclencheur de la vague hallyu du début des années 2000 — et continue d''attirer environ **3.3 millions de visiteurs par an (dont 1.3 million d''étrangers)**, ce qui en fait la destination touristique unique la plus visitée de Corée après Séoul, Busan et Jeju. \n\nDepuis le **1er mars 2006**, l''île se présente comme la **« Naminara Republic »** autoproclamée, avec son propre drapeau, sa monnaie (les pièces Nami Tongbo), son passeport et son service postal — un concept de marketing touristique plutôt qu''une entité politique réelle. \n\nL''emblématique **allée bordée de métaséquoias** (la voie enneigée iconique de Winter Sonata), l''**allée des ginkgos des amoureux au bord de la rivière** sur le côté sud, la **route des pins de Corée** et le **pont Sequoia** en verre recyclé, fabriqué à partir de bouteilles de soju, se parcourent tous à pied en deux heures tranquilles. La faune de l''île comprend des paons (dont de rares albinos), des autruches, des lapins sauvages et des écureuils. \n\n**Les frais de VISA de la Naminara Republic (ferry aller-retour inclus) sont compris dans le prix de ce circuit**.","visitBasics":{"hours":"Ferry à partir de 08:00, dernier bateau au retour à 21:00, environ toutes les 10-20 minutes au fil de la journée ; la plupart des boutiques de l''île ferment vers 18:00. Les horaires d''hiver peuvent changer selon la météo","closed":"Ouvert toute l''année","admission":"Frais de visa de la Naminara Republic, ferry aller-retour inclus : adulte ₩19,000 — INCLUS dans ce circuit","walking":"Facile — chemins plats bordés d''arbres, même s''ils peuvent être verglacés au cœur de l''hiver. Le tour du demi-périmètre fait environ 3 km. La location de vélos et de voiturettes électriques est disponible sur l''île, à vos frais"},"image":"/images/tours/nami-island/nami-metasequoia-sunset-lake.webp","images":["/images/tours/nami-island/nami-metasequoia-sunset-lake.webp","/images/tours/nami-island/kakaotalk-20260510-222949305-04.webp","/images/tours/nami-island/kakaotalk-20260510-222949305-05.webp","/images/tours/nami-island/chatgpt-image-2026-5-11-01-12-05.webp"],"imageCredits":[{"url":"/images/tours/nami-island/nami-metasequoia-sunset-lake.webp","source":"atoc-korea"},{"url":"/images/tours/nami-island/kakaotalk-20260510-222949305-04.webp","source":"atoc-korea"},{"url":"/images/tours/nami-island/kakaotalk-20260510-222949305-05.webp","source":"atoc-korea"},{"url":"/images/tours/nami-island/chatgpt-image-2026-5-11-01-12-05.webp","source":"atoc-korea"}],"galleryItems":[{"id":1,"type":"photo","src":"/images/tours/nami-island/nami-metasequoia-sunset-lake.webp","location":"Île de Nami (Namiseom)","caption":"Île de Nami (Namiseom) — photo 1","alt":"Île de Nami (Namiseom) — gallery image 1"},{"id":2,"type":"photo","src":"/images/tours/nami-island/kakaotalk-20260510-222949305-04.webp","location":"Île de Nami (Namiseom)","caption":"Île de Nami (Namiseom) — photo 2","alt":"Île de Nami (Namiseom) — gallery image 2"},{"id":3,"type":"photo","src":"/images/tours/nami-island/kakaotalk-20260510-222949305-05.webp","location":"Île de Nami (Namiseom)","caption":"Île de Nami (Namiseom) — photo 3","alt":"Île de Nami (Namiseom) — gallery image 3"},{"id":4,"type":"photo","src":"/images/tours/nami-island/chatgpt-image-2026-5-11-01-12-05.webp","location":"Île de Nami (Namiseom)","caption":"Île de Nami (Namiseom) — photo 4","alt":"Île de Nami (Namiseom) — gallery image 4"}]},{"number":5,"time":"≈ 16:45","duration":"45 min","name":"Mur de glace de la vallée d''Eobi","category":"Fête villageoise d''hiver (saisonnière)","description":"La vallée d''Eobi — 어비계곡, d''après les caractères signifiant « poisson volant », en souvenir d''une eau autrefois assez rapide pour donner l''impression que les poissons s''envolaient — est une vallée de trois kilomètres à Seorak-myeon, dans le sud de Gapyeong. L''été, c''est une rivière de baignade et à truites. L''hiver, elle devient quelque chose dont le reste de l''année ne donne aucun indice.\n\n**Ici, le mur de glace est fabriqué, pas trouvé.** Depuis l''hiver 2023, les habitants de Garil 2-ri pulvérisent de l''eau sur la paroi rocheuse de la vallée pendant les semaines les plus froides et laissent le froid faire le reste, jusqu''à en faire une nappe dont la hauteur est rapportée à environ **25 mètres**. L''ensemble est géré par l''association des habitants du village — une trentaine de personnes — comme un projet de revenu hors saison pour une vallée qui, auparavant, n''avait presque aucun visiteur en hiver. Vous le verrez décrit ailleurs, y compris sur certaines pages touristiques officielles, comme une cascade gelée naturelle. Ce n''en est pas une, et il n''en est que plus impressionnant.\n\nL''observation se fait depuis une **passerelle en bois** qui longe la vallée, issue d''un projet de réhabilitation de la province de Gyeonggi qui a également apporté l''éclairage nocturne. **Le sol directement sous le mur est fermé** après que des visiteurs s''y sont blessés en glissant : les photographies se prennent donc depuis la zone d''observation prévue, et non par en dessous. À côté du mur, le village exploite une piste de luge sur glace, une luge à neige tournante, un igloo pour les photos et une petite serre-jardin chauffée.\n\nNous arrivons en fin d''après-midi, peu avant la fin des horaires que le village publie pour le site du festival. Au cœur de l''hiver, cela signifie les derniers restes de lumière du jour sur la glace — bon pour les photographies, et froid. En pleine saison, le village allume bien l''éclairage de la passerelle, mais il s''allume à peu près à l''heure de fermeture : cet itinéraire ne le promet donc pas. De petits frais sont perçus sur place par le village pour la zone d''observation et pour les activités de luge ; ils sont fixés localement et changent d''une année à l''autre.","image":null,"highlights":["Un mur de glace d''environ 25 m selon les chiffres rapportés, fait grandir sur la paroi rocheuse de la vallée par les habitants de Garil 2-ri depuis l''hiver 2023 — construit, et non naturel","Géré par l''association des habitants du village (environ 30 personnes) comme un projet hors saison, sous le nom 어비계곡 겨울나라, « le pays d''hiver de la vallée d''Eobi »","Passerelle d''observation en bois avec éclairage nocturne, ajoutée dans le cadre du programme de réhabilitation des vallées propres de la province de Gyeonggi","Luge sur glace, luge à neige tournante, igloo pour les photos et serre-jardin chauffée à côté du mur","Le nom de la vallée, 어비 (魚飛), signifie « poisson volant » — d''après une eau autrefois assez rapide pour donner l''impression que les poissons volaient","La fréquentation a environ doublé pour atteindre quelque 60,000 visiteurs en une saison à mesure que le bouche-à-oreille se répandait, surtout auprès des voyageurs d''Asie du Sud-Est"],"timeUsed":["L''autocar se gare et le guide accompagne le groupe jusqu''à l''entrée de la vallée (~10 min)","Passerelle jusqu''à la zone d''observation du mur de glace et photographies (~25 min)","Luge ou serre-jardin en option, ou retour anticipé à l''autocar pour se réchauffer (~10 min)"],"whyOnRoute":"Eobi clôt la journée pour deux raisons. Géographiquement, c''est la seule étape située du côté de Séoul sur cet itinéraire — Seorak-myeon se trouve dans le sud de Gapyeong, déjà orienté vers le retour — si bien qu''une heure ici ne coûte aucun trajet supplémentaire au terme d''une longue journée. Éditorialement, c''est la raison pour laquelle cet itinéraire est un produit d''hiver plutôt qu''un produit annuel : le Seoraksan et Nami se visitent en toute saison, mais le mur de glace n''existe peut-être que huit semaines, et seulement si le froid tient. C''est aussi l''étape dont la plupart des voyageurs n''ont jamais entendu parler, ce qui fait une bonne note finale.","_poi_meta":{"match":"authored","poi_key":"eobi_ice_valley","sources":["Kyeongin Ilbo (경인일보) — reportages sur le 인공빙벽 (mur de glace artificiel) de la vallée d''Eobi à Gapyeong et sur l''association des habitants de Garil 2-ri qui l''exploite","Office du tourisme du comté de Gapyeong (gptour.go.kr) — fiche de la vallée d''Eobi, Garil-ri, Seorak-myeon","Korea Tourism Organization (VisitKorea — fiche de la vallée d''Eobigyegok ; à noter que le texte anglais de la KTO décrit le mur comme naturel, ce que la documentation en langue coréenne contredit)","Informations officielles du festival 어비계곡 겨울나라 — dates de la saison, frais sur place et activités","Programme de réhabilitation des vallées propres de la province de Gyeonggi (청정계곡 정비사업) — passerelle et éclairage nocturne"],"verified":true,"verified_date":"2026-08-04"},"smartNotes":{"photo":"Photographiez depuis la zone d''observation prévue sur la passerelle — le dessous du mur est clôturé. La fin d''après-midi vous donne la lumière du jour déclinante sur la glace, puis l''éclairage de la passerelle ; les deux fonctionnent, et la transition entre les deux est la meilleure fenêtre.","facilities":"Géré par le village et sommaire : une serre-jardin chauffée, une piste de luge et de petits stands. Ne comptez pas sur une vraie restauration ni sur un grand espace intérieur pour se réchauffer.","tip":"Portez des chaussures d''hiver antidérapantes et considérez le mur de glace comme dépendant de la météo plutôt que garanti — un redoux le fait rétrécir et le village décide lui-même de son ouverture. Prévoyez un peu de monnaie pour les frais sur place."},"visitBasics":{"hours":"Géré par le village et saisonnier. Le village annonce 10:00-17:00 pour le site du festival (Eobi Valley Village, 031-585-3551). Cet itinéraire arrive vers la fin de ce créneau : les activités payantes peuvent donc déjà fermer ; la vallée et sa passerelle ne sont pas un site à accès contrôlé. Les horaires sont fixés localement chaque année","closed":"Hiver uniquement — provisoirement de la mi-décembre à la mi-février. Le village fixe les dates chaque année : il s''agit donc d''un repère et non d''un calendrier publié. La saison 2025-26 s''est déroulée du 20 décembre au 19 février, et les dates 2026-27 ne sont pas encore annoncées. Le mur n''apparaît qu''une fois le froid installé ; janvier et début février sont les semaines les plus fiables","admission":"Non inclus. Le village demande environ ₩1,000 par personne pour la zone d''observation du mur de glace ; les forfaits luge et activités coûtent en plus de l''ordre de ₩5,000 à ₩30,000. Le parking à l''entrée du village est gratuit, et il reste environ 500 m à pied sur la passerelle de la vallée jusqu''au site. Les tarifs sont fixés localement et changent d''une année à l''autre ; le guide confirme ceux du jour dans l''autocar","walking":"Court mais réellement verglacé. Une passerelle en bois, en grande partie plate, mène à la zone d''observation ; l''accès et les abords sont glissants et des chaussures antidérapantes sont indispensables. Le sol directement sous le mur de glace est fermé aux visiteurs. Ne convient ni aux fauteuils roulants ni aux poussettes"},"images":[],"imageCredits":[],"galleryItems":[]},{"number":6,"time":"≈ 19:00","duration":"≈ 1.5 heure de route","name":"Retour à Séoul (station Myeongdong ou station Hongik University)","category":"Dépose au retour","description":"Le départ de la vallée d''Eobi se fait vers 17:30 pour environ 1.5 heure de route jusqu''à Séoul. Les déposes se font dans l''ordre inverse de la prise en charge : **station Myeongdong vers 19:00**, puis **station Hongik University vers 19:30**.\n\nToutes deux sont des correspondances de métro. Les conditions hivernales sont la principale variable sur ce tronçon — la neige sur les routes de Gapyeong ou la circulation du vendredi et du dimanche soir peuvent ajouter 30-60 minutes, et le guide donnera l''estimation en temps réel de l''autocar sur le trajet. C''est une longue journée ; la plupart des clients dorment pendant ce segment.","image":null,"highlights":[],"timeUsed":["Départ de la vallée d''Eobi (~17:30)","Trajet sur autoroute jusqu''à Séoul (~1.5 heure, plus long par temps de neige ou circulation de week-end)","Dépose à la station Myeongdong (~19:00)","Dépose à la station Hongik University (~19:30)"],"whyOnRoute":"Terminer à Eobi est ce qui garde le retour court : la vallée est déjà l''étape la plus proche de Séoul sur cet itinéraire, l''autocar est donc orienté vers le retour dès qu''il repart. Inverser l''ordre des déposes signifie que les clients de Myeongdong, montés en dernier, descendent en premier.","_poi_meta":null,"images":[],"imageCredits":[],"galleryItems":[]}],"routeFlowStops":[{"name":"Prise en charge (Hongik / Myeongdong)","type":"origin","theme":"Seoul pickup"},{"name":"Parc national de Seoraksan","type":"primary","theme":"Winter mountain"},{"name":"Déjeuner près de Sokcho","type":"secondary","theme":"Lunch break"},{"name":"Île de Nami","type":"primary","theme":"K-drama island"},{"name":"Mur de glace de la vallée d''Eobi","type":"primary","theme":"Ice wall"},{"name":"Retour à Séoul","type":"return","theme":"Drop-off"}],"routePhases":[{"phase":"Séoul → Seoraksan","duration":"≈ 3.5 heures","description":"Prise en charge à 06:00 à Hongik / 06:30 à Myeongdong, puis environ 3 heures de route vers le nord-est sur l''autoroute Séoul-Yangyang avec un arrêt confort, pour arriver à l''entrée de Sogongwon vers 09:30."},{"phase":"Seoraksan","duration":"≈ 2 heures","description":"Temps libre à l''entrée de Sogongwon : le grand Bouddha de bronze Tongildaebul, le temple Sinheungsa et les sentiers de la basse vallée sous la neige. Le téléphérique n''est pas inclus et ne fonctionne que si le vent et la glace le permettent."},{"phase":"Déjeuner → île de Nami","duration":"≈ 3 heures","description":"Déjeuner près de Sokcho (à vos frais), puis environ 2 heures de route pour revenir vers l''ouest jusqu''au quai de Gapyeong et la traversée de cinq minutes en ferry vers l''île de Nami, pour deux heures parmi les allées de métaséquoias givrées."},{"phase":"Vallée d''Eobi → Séoul","duration":"≈ 2.5 heures","description":"Quarante minutes vers le sud jusqu''à la vallée d''Eobi pour le mur de glace dans la lumière de fin d''après-midi, puis environ 1.5 heure de route jusqu''à Séoul — Myeongdong vers 19:00, Hongik vers 19:30."}],"routeShapeIntro":{"title":"Le déroulé de cette journée d''hiver","subtitle":"Un départ à 06:00 à Hongik / 06:30 à Myeongdong et environ 3 heures de route vers le nord-est vous amènent au Seoraksan en milieu de matinée, quand la neige est encore propre et que la lumière est posée sur le granit. Déjeuner près de Sokcho, puis le long retour vers l''ouest par le corridor de Chuncheon jusqu''à l''île de Nami pour les allées d''arbres givrées. La dernière étape, la vallée d''Eobi, se trouve dans le sud de Gapyeong, déjà orientée vers Séoul — vous l''atteignez en fin d''après-midi, peu avant la fin des horaires du village. Retour à Séoul vers 19:00-19:30."},"whyTourWorks":{"bestFor":["Les voyageurs qui visitent la Corée en janvier ou en février et veulent le paysage d''hiver, pas une journée en ville","Les photographes en quête de neige sur le granit, d''allées d''arbres givrées et d''un mur de glace à l''heure bleue","Les couples et les petits groupes à l''aise avec une journée longue, froide et bien remplie","Toute personne qui veut voir quelque chose que la plupart des excursions au départ de Séoul n''incluent pas"],"lessIdealFor":["Toute personne voyageant hors de la saison hivernale — le mur de glace n''existe tout simplement pas pendant les mois doux","Les voyageurs sensibles au froid, ou qui ont besoin de visites garanties quelle que soit la météo","Les clients qui souhaitent marcher le moins possible — le sol est verglacé et la dernière étape se fait sur une passerelle","Les jeunes enfants et toute personne peu assurée sur ses jambes en conditions hivernales"],"routeLogicSections":[{"title":"Rythme et géographie","icon":"route","iconBg":"bg-sky-50/80","iconColor":"text-sky-600","items":[{"label":"Le Seoraksan en premier, tant que la neige est encore propre","detail":"Le parc est le point le plus éloigné de la journée et celui que la fonte et les nuages de l''après-midi affectent le plus. Y aller en premier profite de la lumière la plus claire et de la neige la plus fraîche, et cela signifie que le long trajet se fait avant que quiconque ne soit fatigué."},{"label":"Nami au milieu, parce que le ferry a besoin de la lumière du jour","detail":"Ce qui fait l''intérêt de Nami en hiver, ce sont ses allées d''arbres sous le givre, et elles ont besoin de lumière pour que la traversée en vaille la peine. Un créneau en milieu d''après-midi vous fait traverser tant que l''île est encore lumineuse et avant que le vent ne se lève sur le pont exposé du ferry."},{"label":"Eobi en dernier, parce que c''est déjà sur le chemin du retour","detail":"La vallée d''Eobi se trouve à Seorak-myeon, dans le sud de Gapyeong, du côté de Séoul par rapport à tout le reste de cet itinéraire. Terminer là n''impose aucun détour, et au cœur de l''hiver l''arrivée tardive coïncide avec l''allumage de l''éclairage nocturne de la vallée le long de la passerelle."},{"label":"Un itinéraire construit autour d''une seule saison courte","detail":"Le mur de glace n''existe que tant que le froid tient — le village commence à le construire à la mi-décembre et il disparaît en février. Cette seule contrainte explique pourquoi cet itinéraire existe et pourquoi il ne fonctionne pas le reste de l''année."}]}]},"practicalAccordionItems":[{"id":"pickup","title":"Prise en charge et dépose","preview":"Deux points de prise en charge à Séoul : le Starbucks de la sortie 8 de la…","content":["Deux points de prise en charge à Séoul : le Starbucks de la sortie 8 de la station Hongik University à 06:00 (Mapo-gu), et la sortie 2 de la station Myeongdong, près du magasin phare NorthFace, à 06:30 (Jung-gu).","Les deux prises en charge partagent le même autocar ; merci d''être à votre point de rendez-vous 5 minutes en avance.","Déposes au retour dans l''ordre inverse : Myeongdong ≈19:00, Hongik University ≈19:30.","La durée effective de votre journée dépend du point de prise en charge : ≈13.5 heures depuis Hongik, ≈12.5 heures depuis Myeongdong."]},{"id":"what-to-bring","title":"Quoi porter et emporter","preview":"Des chaussures d''hiver antidérapantes — l''élément le plus important. Les tr…","content":["Des chaussures d''hiver antidérapantes — l''élément le plus important. Les trois étapes ont de la glace au sol.","De vraies couches pour le froid : attendez-vous à −5 °C ou moins au Seoraksan avec un refroidissement éolien important, et à des températures de crépuscule à Eobi.","Gants, bonnet et de quoi couvrir vos oreilles. Le pont du ferry de Nami est entièrement exposé.","Un peu de monnaie pour les frais perçus par le village à Eobi et pour le déjeuner (₩10,000-15,000).","Un appareil photo ou un smartphone, plus une batterie de rechange — le froid vide les batteries vite, et c''est un itinéraire que les gens photographient beaucoup."]},{"id":"weather-policy","title":"Politique météo","preview":"Il s''agit d''un circuit de saison hivernale, et la météo fait partie du prod…","content":["Il s''agit d''un circuit de saison hivernale, et la météo fait partie du produit, elle n''en est pas une exception.","Le mur de glace d''Eobi n''est pas garanti. Il est construit par les villageois au fil des semaines les plus froides et un redoux le fait rétrécir ou disparaître. Le village décide lui-même de son ouverture. Si le mur n''est pas visible à votre date, nous vous le dirons avant le départ et vous proposerons un report ou le remboursement de cette partie.","Le téléphérique du Seoraksan n''est pas garanti non plus. Ses horaires changent chaque jour et il est suspendu par vent fort ou par verglas. Il n''est pas inclus dans le prix, rien n''est donc perdu s''il ne fonctionne pas.","Fortes chutes de neige : l''autocar est équipé de pneus hiver et le circuit a normalement lieu malgré tout, mais le retour peut prendre une heure de plus. De la neige sévère ou des routes fermées peuvent annuler entièrement le départ — un remboursement intégral s''applique alors.","Le ferry de Nami peut être suspendu par gros mauvais temps ; si cela se produit, le guide prolonge les autres étapes et l''entrée de Nami est remboursée."]},{"id":"season-window","title":"Quand ce circuit fonctionne","preview":"Cet itinéraire est réservé à l''hiver. Il existe parce que le mur de glace d…","content":["Cet itinéraire est réservé à l''hiver. Il existe parce que le mur de glace de la vallée d''Eobi existe, et celui-ci est une structure saisonnière bâtie par un village, pas une attraction permanente.","Le mur commence généralement à se former à partir de la mi-décembre, une fois l''eau de la vallée gelée, et il est le plus fiable en janvier et début février.","La fin de saison varie d''une année à l''autre — la saison 2025-26 s''est achevée le 19 février. Les dates de l''hiver à venir sont fixées par le village et confirmées à la réservation.","Hors saison, le même duo Seoraksan et île de Nami est disponible toute l''année sur notre excursion d''une journée Seoraksan + île de Nami + Garden of Morning Calm."]},{"id":"inclusions","title":"Ce qui est inclus","preview":"Deux points de prise en charge à Séoul et les deux mêmes points de dépose…","content":["Deux points de prise en charge à Séoul et les deux mêmes points de dépose, autocar chauffé, guide anglophone licencié.","Entrée du parc national de Seoraksan — GRATUITE depuis mai 2023, aucun billet nécessaire.","Ferry aller-retour vers l''île de Nami + frais de visa de la Naminara Republic (₩19,000) — INCLUS.","Péages et frais de stationnement — INCLUS.","Non inclus : le déjeuner et les boissons (₩10,000-15,000, à vos frais), le téléphérique du Seoraksan (₩16,000 adulte aller-retour, billets sur place uniquement et dépendant de la météo), les frais sur place du village à la vallée d''Eobi (la zone d''observation du mur de glace a été facturée environ ₩1,000 par personne, les activités de luge en supplément), la location de vélos ou de voiturettes électriques à Nami, et les dépenses personnelles.","Guide sinophone disponible sur demande — merci de réserver au moins 3 jours à l''avance."]},{"id":"language","title":"Langue","preview":"Langue principale du circuit : l''anglais.","content":["Langue principale du circuit : l''anglais.","Guide sinophone disponible sur demande — réservez au moins 3 jours à l''avance.","Le coréen est parlé toute la journée pour les menus, la signalétique et les échanges avec les stands ; le guide se charge de la traduction."]},{"id":"walking","title":"Marche et terrain","preview":"Modérée, et la difficulté tient ici à la glace plutôt qu''à la distance ou a…","content":["Modérée, et la difficulté tient ici à la glace plutôt qu''à la distance ou au dénivelé.","Seoraksan : chemins pavés et marches dans la vallée jusqu''au Sinheungsa et au Tongildaebul, enneigés et glissants par endroits. Aucune randonnée n''est prévue et aucun sommet n''est tenté.","Île de Nami : allées plates, pavées et bordées d''arbres, environ 3 km en deux heures, verglacées au cœur de l''hiver.","Vallée d''Eobi : une courte passerelle en bois, en grande partie plate, jusqu''à la zone d''observation — mais l''accès et les abords sont réellement glissants. Le sol sous le mur de glace est fermé aux visiteurs.","Des chaussures d''hiver antidérapantes sont indispensables aux trois étapes. Des baskets ordinaires ne suffisent pas sur cet itinéraire. Les poussettes et les fauteuils roulants ne conviennent pas à Eobi."]},{"id":"lunch","title":"Déjeuner (à vos frais)","preview":"Le déjeuner est pris vers 11:45 près du Seoraksan ou du côté de Sokcho, jus…","content":["Le déjeuner est pris vers 11:45 près du Seoraksan ou du côté de Sokcho, juste après le parc.","Les choix de la côte est : hoedeopbap (poisson cru sur du riz), poisson grillé, ou le célèbre sundubu jjigae de Sokcho, un ragoût de tofu soyeux.","Comptez environ ₩10,000-15,000 par personne ; les espèces et la carte sont normalement acceptées.","L''arrêt est volontairement enlevé, 50 minutes — les deux étapes restantes dépendent du temps. Les options végétariennes sont limitées : prévenez donc le guide le matin."]},{"id":"cancellation","title":"Annulation","preview":"Annulation gratuite jusqu''à 24 heures avant la prise en charge.","content":["Annulation gratuite jusqu''à 24 heures avant la prise en charge.","Moins de 24 heures : remboursement de 50%.","Absence ou prise en charge manquée : aucun remboursement — mais contactez les opérations d''AtoC Korea dans les 10 minutes suivant l''heure de prise en charge et l''autocar peut brièvement attendre s''il est en avance sur l''horaire."]}],"practicalWeatherStatic":{"today":{"temp":"—","label":"Voir les notes saisonnières"},"tomorrow":{"temp":"—","label":"Voir les notes saisonnières"},"_seasonalSummary":"Seoul + Gangwon: temperate four-season climate. Seoraksan is 5-7°C cooler than Seoul year-round. Hot humid summers (Jun-Aug), crisp cold winters (Dec-Feb), with prime seasons in spring (April cherry blossoms) and autumn (October-November foliage)."},"seasonalVariations":[{"season":"Mi-décembre","description":"Le mur de glace commence à se former une fois que l''eau de la vallée gèle pour de bon. En début de saison, il est plus petit et le village peut encore être en train de le monter. Le Seoraksan a en général sa première neige installée."},{"season":"Janvier","description":"Le meilleur mois, et de loin. Le mur de glace est à sa pleine hauteur, la couverture neigeuse du Seoraksan est la plus fiable et les allées d''arbres de Nami sont correctement givrées. Les températures les plus froides de l''année — habillez-vous en conséquence."},{"season":"Début février","description":"Encore fiable la plupart des années, et avec un peu plus de lumière du jour à l''étape d''Eobi. Surveillez les redoux, qui font rétrécir le mur rapidement."},{"season":"Hors saison hivernale","description":"Le circuit ne fonctionne pas. Le mur de glace a disparu à la fin février et Eobi redevient une vallée de baignade estivale. Pour le Seoraksan et Nami hors de l''hiver, voyez notre excursion d''une journée Seoraksan + île de Nami + Garden of Morning Calm."}],"bookingTrustItems":[{"icon":"check-circle","title":"Toutes les entrées incluses","description":"Ferry de Nami + Morning Calm regroupés","iconBg":"bg-emerald-50/80","iconColor":"text-emerald-600","body":"Les entrées du ferry de l''île de Nami (₩19,000) et du Garden of Morning Calm (₩11,000) sont prépayées dans le prix du circuit — aucune file de billetterie à chaque étape. L''entrée du Seoraksan est GRATUITE (supprimée en mai 2023). Économie totale sur les entrées : environ ₩30,000."},{"icon":"users","title":"Guide anglophone licencié","description":"Guide touristique licencié en Corée","iconBg":"bg-pink-50/80","iconColor":"text-pink-600","body":"Guide licencié par la Korea Tourism Organization et parlant couramment anglais ; guide sinophone disponible sur demande préalable. Le commentaire du guide couvre l''histoire du temple de l''époque Silla au Seoraksan, l''héritage Winter Sonata de Nami et l''histoire du fondateur de Morning Calm."},{"icon":"shield","title":"Tarification transparente","description":"Aucun arrêt shopping caché","iconBg":"bg-sky-50/80","iconColor":"text-sky-600","body":"Pas de boutiques de ginseng, pas de duty-free, pas de détours souvenirs commissionnés. Chaque minute de cette journée de 13.5 heures se passe sur un site ou en trajet — ce que vous réservez est ce que vous vivez."}],"bookingSupportSteps":[{"timing":"Immédiatement","title":"Confirmation instantanée","detail":"Confirmation de réservation avec choix du point de prise en charge","description":"Confirmation de réservation instantanée avec choix du point de prise en charge Hongik/Myeongdong."},{"timing":"La veille","title":"Détails de la prise en charge","detail":"Lieu exact de prise en charge et informations sur le véhicule par WhatsApp/SMS","description":"Vérification météo, numéro de plaque de l''autocar et éventuelles notes saisonnières sur l''itinéraire (horaires du festival des lumières de Morning Calm, pic des feuillages au Seoraksan, etc.) envoyés la veille."},{"timing":"Le matin même","title":"Confirmation de la prise en charge","detail":"Identification du guide au point de rendez-vous 10 min avant le départ","description":"Le guide attend au Starbucks de la sortie 8 de Hongik à partir de 05:50 ; à la sortie 2 de Myeongdong (NorthFace) à partir de 06:20. Une photo du guide et de l''autocar vous est envoyée sur WhatsApp la veille au soir."},{"timing":"Pendant le circuit","title":"Assistance pendant le circuit","detail":"Commentaire du guide à chaque étape + assistance opérationnelle 24h/24 et 7j/7","description":"Le guide assure un commentaire sur place sur la fondation du Seoraksan en 652 apr. J.-C. sous les Silla, sur l''origine de Nami avec le barrage de Cheongpyeong en 1944 et son héritage Winter Sonata de 2002, ainsi que sur la conception de Morning Calm en 1992 et son ouverture en 1996."},{"timing":"En fin de journée","title":"Deux points de dépose","detail":"Myeongdong ~19:00 / Hongik ~19:30","description":"Au retour, l''autocar dépose aux deux points de prise en charge, dans l''ordre inverse."},{"timing":"Après le circuit","title":"Avis et suivi","detail":"Avis facultatif après le circuit","description":"Une demande de retour d''expérience est envoyée après le circuit ; les recommandations de restaurants ou de sites pour le reste de votre séjour à Séoul reçoivent une réponse le jour même."}],"staticQuestions":[{"question":"Le mur de glace d''Eobi est-il naturel ?","answer":"Non — et nous préférons vous le dire plutôt que vous laisser le découvrir sur place. Depuis l''hiver 2023, les habitants du village de Garil 2-ri pulvérisent de l''eau sur la paroi rocheuse de la vallée pendant les semaines les plus froides et la laissent geler en une nappe dont la hauteur est rapportée à environ 25 mètres. Vous le verrez décrit comme une cascade gelée naturelle sur certains sites touristiques, y compris officiels et en anglais. C''est inexact. C''est un spectacle bâti par un village, animé par une trentaine d''habitants comme projet de revenu hors saison, et nous trouvons que c''est une meilleure histoire que celle des brochures."},{"question":"Le mur de glace est-il garanti ?","answer":"Non, et tout circuit qui le garantit promet plus qu''il ne peut tenir. Le mur dépend d''un froid durable et de la décision du village d''ouvrir — un redoux le fait rétrécir. S''il n''est pas visible à votre date de départ, nous vous le dirons avant votre voyage et vous proposerons un report ou le remboursement de cette partie. Il est le plus fiable en janvier et début février."},{"question":"À quelles dates exactement ce circuit fonctionne-t-il ?","answer":"En hiver uniquement. Le mur de glace commence généralement à se former à partir de la mi-décembre et la saison 2025-26 s''est achevée le 19 février. Les dates exactes sont fixées chaque année par le village qui construit le mur : nous confirmons donc la fenêtre d''exploitation à la réservation plutôt que de publier un calendrier fixe que nous ne pourrions pas tenir."},{"question":"Le téléphérique du Seoraksan est-il inclus ?","answer":"Non. Le téléphérique de Gwongeumseong coûte ₩16,000 par adulte aller-retour, se vend uniquement sur place et ne peut pas être réservé à l''avance. En hiver, son exclusion compte plus que d''habitude : ses horaires d''exploitation changent chaque jour et il est suspendu par vent fort ou par verglas, ce n''est donc réellement pas quelque chose que nous pouvons promettre. L''entrée du parc elle-même est gratuite, et ce depuis mai 2023."},{"question":"Fait-il vraiment si froid ?","answer":"Assez froid pour que les chaussures et les couches décident si vous appréciez la journée. Attendez-vous à environ −5 °C à +5 °C sur le fond de vallée du Seoraksan avec un fort refroidissement éolien, et plus froid à l''ombre. Le pont du ferry de Nami est entièrement exposé. À Eobi, vous êtes immobile, au crépuscule, à côté d''un mur de glace. Emportez des gants, un bonnet et de quoi couvrir vos oreilles."},{"question":"Quelles chaussures me faut-il ?","answer":"Des chaussures ou des bottes d''hiver antidérapantes. C''est le seul équipement sur lequel nous insistons. Les trois étapes ont de la glace au sol — les chemins en marches de la vallée du Seoraksan, les allées plates de Nami, et la passerelle d''Eobi et son accès. Des baskets ordinaires ne conviennent pas. Nous n''exigeons ni ne fournissons de crampons ; la marche est courte, c''est la surface qui pose problème."},{"question":"Y a-t-il beaucoup de marche ?","answer":"Pas beaucoup de distance — la difficulté tient à la surface, pas à la longueur. Le Seoraksan n''utilise que les sentiers de basse vallée près de l''entrée, sans randonnée ni tentative de sommet. Nami est plate, environ 3 km en deux heures si vous faites le demi-périmètre. Eobi est une courte passerelle. Mais tout cela est verglacé : prévoyez donc plus de temps et de prudence que les distances ne le laissent penser."},{"question":"Est-ce adapté aux enfants ou aux voyageurs âgés ?","answer":"Moins que nos autres excursions à la journée, et nous vous orienterions ailleurs si l''un ou l''autre cas s''applique nettement. C''est une journée de 13.5 heures qui commence à 06:00, dans le froid du plein hiver, avec un sol verglacé à chaque étape. La passerelle d''Eobi ne convient ni aux poussettes ni aux fauteuils roulants, et le sol sous le mur de glace est clôturé. Les enfants qui aiment la neige et sont bien habillés s''en sortent très bien ; les marcheurs peu assurés, non."},{"question":"Y a-t-il des frais à payer sur place ?","answer":"Oui, de deux sortes. Le déjeuner est à vos frais, environ ₩10,000-15,000. À Eobi, le village perçoit de petits frais sur place — la zone d''observation du mur de glace a été facturée autour de ₩1,000 par personne, la luge en supplément. Ils sont fixés localement et changent d''une année à l''autre : emportez donc un peu de monnaie, et le guide confirmera les montants du jour dans l''autocar. L''entrée du parc de Seoraksan est gratuite, et le ferry et l''entrée de Nami sont déjà inclus."},{"question":"Pourquoi arrivons-nous si tard à Eobi ?","answer":"À cause de sa position. La vallée d''Eobi se trouve dans le sud de Gapyeong, plus près de Séoul que le Seoraksan ou Nami : la visiter en dernier signifie donc que l''autocar est déjà orienté vers le retour et que le trajet final reste court. Au cœur de l''hiver, une arrivée à 16:45 vous fait voir les derniers restes de lumière du jour sur la glace, puis l''allumage de l''éclairage de la passerelle, ce qui est une bonne fenêtre pour les photographies — mais c''est aussi le moment le plus froid de la visite, alors habillez-vous pour rester immobile en extérieur."},{"question":"En quoi ce circuit diffère-t-il de vos autres circuits au Seoraksan ?","answer":"Par la troisième étape et par la saison. Notre excursion au Seoraksan proposée toute l''année associe le parc à l''île de Nami et au Garden of Morning Calm — une journée plus douce, centrée sur les jardins, qui fonctionne par tous les temps. Celle-ci remplace le jardin par le mur de glace d''Eobi et n''existe que tant que le mur existe. Si vous voyagez en dehors de janvier et février, c''est l''itinéraire annuel qu''il vous faut."},{"question":"Que se passe-t-il en cas de fortes chutes de neige ?","answer":"Le circuit a généralement lieu malgré tout — l''autocar est équipé de pneus hiver en saison et la neige est plutôt le but recherché. Comptez jusqu''à une heure de plus sur le trajet de retour. Si les chutes de neige sont assez sévères pour fermer les routes, nous annulons le départ et remboursons intégralement. Nous préférons annuler plutôt que faire une journée de 13.5 heures en montagne dans des conditions dangereuses."}],"guestReviews":[],"reviewsSummary":{"averageRating":0,"totalReviews":0,"ratingDistribution":[{"stars":5,"count":0,"percentage":0},{"stars":4,"count":0,"percentage":0},{"stars":3,"count":0,"percentage":0},{"stars":2,"count":0,"percentage":0},{"stars":1,"count":0,"percentage":0}],"highlights":[]},"sticky_booking_bar":{"note":"Saison hivernale uniquement — sélectionnez votre date pour vérifier si le mur de glace fonctionne et finaliser votre réservation.","price":{"amountLabel":"69","currency":"USD","per":"person","salePriceUsd":69}},"pickup_dropoff":{"primary":{"name":"Starbucks Hongik University Station Exit 8","address":"Yanghwa-ro, Mapo-gu, Seoul (in front of the Starbucks at Hongik University Station Exit 8)","time":"prise en charge 06:00 / dépose 19:30","instructions":"Retrouvez le guide devant la devanture du Starbucks située immédiatement au-dessus de la sortie 8 de la station Hongik University. Cherchez le panneau AtoC Korea et l''autocar dans la file de prise en charge."},"alternates":[{"name":"Myeongdong Station Exit 2 (NorthFace flagship)","address":"Toegye-ro, Jung-gu, Seoul (NorthFace flagship store at Myeongdong Station Exit 2)","time":"prise en charge 06:30 / dépose 19:00","instructions":"Retrouvez le guide devant le magasin phare NorthFace, en haut de la sortie 2 de la station Myeongdong."}]},"matching_profile":{"profile_version":1,"is_active":true,"product_id":"seoul-winter-seoraksan-nami-eobi-ice-valley-day-tour","product_type":"bus","route_type":"fixed_route","destination_region":"seoul_gangwon","region_type":"gangwon_seoraksan","vehicle_type":"large_coach","duration_hours":13.5,"region_tags":["seoul_mapo","seoul_jung","gangwon_sokcho","gyeonggi_gapyeong"],"theme_tags":["national_park","mountain","buddhist_temple","k_drama_filming","themed_garden","hallyu_landmark"],"poi_tags":["seoraksan_national_park","nami_island","eobi_ice_valley"],"pace_level":0.7,"walking_level":0.6,"scenic_level":1,"photo_level":1,"culture_level":0.85,"relax_level":0.5,"first_time_fit":1,"family_fit":0.7,"senior_fit":0.5,"couple_fit":1,"solo_traveler_fit":0.9,"active_traveler_fit":0.85,"adult_family_fit":0.95,"family_with_teens_fit":0.95,"young_kids_fit":0.5,"senior_active_fit":0.75,"senior_general_fit":0.55,"mobility_friendly_fit":0.4,"stroller_fit":0.2,"one_day_fit":1,"same_day_flight_fit":0.1,"rain_fit":0.3,"value_for_money_fit":1,"iconic_landmark_fit":1,"cafe_fit":0.5,"food_fit":0.5,"nature_fit":1,"beach_fit":0.1,"nightlife_fit":0.1,"shopping_fit":0.25,"no_shopping_fit":1,"local_culture_fit":0.7,"storytelling_fit":0.9,"unesco_fit":0.55,"intangible_heritage_fit":0.5,"indoor_ratio":0.1,"weather_sensitivity":"high","comfort_level":0.55,"budget_fit":1,"premium_fit":0.2,"small_group_fit":0.15,"private_fit":0.05,"bus_fit":1,"price_band":"budget","pickup_base":"seoul_central","return_time_band":"19:00-19:30","duration_band":"13h","min_recommended_age":8,"hard_constraints":{"avoidIf":["mobility_limited","wheelchair_required"],"notIdealFor":["very_low_mobility","young_kids_under_6"]},"walking_notes":["13.5-hour day with ~4-5 km total walking.","Seoraksan paths rocky in places; Nami Island flat; the Eobi Valley deck path is short but icy.","Non-slip winter footwear essential; the ground under the ice wall is closed off.","Cable car at Seoraksan optional, weather-dependent and not included."],"keywords":["seoul seoraksan day tour","nami island day trip","garden of morning calm tour","seoul winter wonder tour","seoraksan nami one day"],"synonym_hints":["seoul to seoraksan day tour","korea three signature stops day trip","seoul winter sonata tour"],"seasonality":"winter_only","pickup_base_normalized":"seoul","vehicle_type_legacy":"bus_coach","anchor_poi_keys":["seoraksan_national_park","nami_island","eobi_ice_valley"],"private_tour_fit":0.05,"customizable_route_fit":0.05,"flexibility_fit":0.2,"fixed_itinerary_fit":1,"national_park_fit":1,"buddhist_temple_fit":0.6,"k_drama_filming_fit":1,"winter_sonata_fit":1,"themed_garden_fit":0,"history_culture_fit":0.65,"religious_history_fit":0.45,"premium_dining_fit":0.15,"seasonal_fit":1,"winter_lighting_festival_fit":0,"autumn_foliage_fit":0,"china_mainland_market_fit":0.85,"korea_domestic_market_fit":0,"taiwan_market_fit":1,"singapore_market_fit":1,"hong_kong_market_fit":1,"china_diaspora_overseas_market_fit":1,"se_asia_market_fit":1,"us_market_fit":0.95,"europe_market_fit":0.95,"australia_market_fit":0.95,"japan_market_fit":1,"first_time_korea_fit":1,"seoul_day_trip_fit":1,"english_speaking_guide_provided":true,"chinese_speaking_guide_available_on_advance_notice":true,"japanese_speaking_guide_available_on_advance_notice":true},"matching_metadata":{"primary_themes":["winter","seasonal","seoul_day_trip","national_park","ice_wall","k_drama_filming"],"secondary_themes":["frozen_waterfall","snow_scenery","winter_sonata","metasequoia_lane","photo_spots","first_time_korea"],"best_for":["winter_travelers","photo_lovers","couples","first_time_korea","snow_seekers"],"not_recommended_for":["travelers_sensitive_to_cold","minimal_walking_seekers","visitors_outside_dec_to_feb"],"anchor_pois":["Seoraksan National Park","Nami Island","Eobi Ice Valley"],"anchor_poi_keys":["seoraksan_national_park","nami_island","eobi_ice_valley"],"competing_products":["seoul-seoraksan-nami-island-morning-calm-day-tour","seoul-seoraksan-national-park-sokcho-beach-day-trip","seoul-seoraksan-naksansa-temple-naksan-beach-day-trip"],"reviews_attribution":"New product (2026-08) — no imported reviews; rating starts at 0.","unesco_fit_note":"Seoraksan is Korea''s first UNESCO Biosphere Reserve (1982) and a UNESCO World Heritage tentative site, but no stop on this route is an inscribed World Heritage property."},"itinerary_variants":[],"_publication":{"schema_version":"v4_canonical","created":"2026-08-04","last_modified":"2026-08-04","version_history":["v1_authored_2026_08_04"],"fix_passes":{"v1_authored_2026_08_04":"New seasonal product (owner instruction 2026-08-04). Winter-only Seoraksan + Nami Island + Eobi Ice Valley coach day tour, running roughly 20 Dec – 28 Feb. Donor seoul-seoraksan-nami-island-morning-calm-day-tour supplied the KB-verified Seoraksan and Nami Island stop bodies plus the two-point Seoul pickup and Seoul-region UI blocks. Eobi Ice Valley, pickup, lunch, return and all product-level copy authored fresh in 6 locales (scripts/seoul-winter-eobi-content/) with de/fr/it/ru staged. Eobi Ice Valley ships without photos — no owned imagery yet. matching_profile derived from the donor with seasonality forced to winter_only and the garden/foliage axes zeroed."}},"page_sections":[]}'::jsonb
)
